package com.lianxibu.site.domain.protocol;
import static org.junit.jupiter.api.Assertions.*;import java.nio.charset.StandardCharsets;import java.time.*;import org.junit.jupiter.api.Test;
class CollectorHostMemoryTelemetryTest {
 String wire="{\"schema_version\":\"collector-host-memory-v1\",\"capture_epoch\":\"00000000-0000-4000-8000-000000000001\",\"process_identity\":\""+"a".repeat(64)+"\",\"capture_started_at\":\"2026-01-01T00:09:00.000000Z\",\"sequence\":1,\"pid\":12,\"observed_at\":\"2026-01-01T00:10:00.000000Z\",\"rss_bytes\":1048576,\"cgroup_epoch\":\""+"b".repeat(64)+"\",\"maximum_bytes\":201326592,\"oom_events\":0,\"oom_kills\":0}";
 byte[] raw(String text){return text.getBytes(StandardCharsets.UTF_8);}
 @Test void ClosedIndependentSnapshotUsesAllOriginalBytesAndDoesNotExtendSevenFieldHeartbeat(){var value=CollectorHostMemoryTelemetry.parse(raw(wire));assertEquals(12,CanonicalJson.parse(value.canonical()).size());assertEquals(1048576,value.sample().rssBytes());assertEquals(201326592,value.sample().maximumBytes());assertEquals(value,CollectorHostMemoryTelemetry.parse(raw(value.canonical())));assertEquals(value,CollectorHostMemoryTelemetry.parse(raw("  "+wire+"  ")));assertEquals("CollectorHostMemoryParsed[redacted]",value.toString());assertEquals("CollectorHostMemorySample[redacted]",value.sample().toString());assertThrows(RuntimeException.class,()->CollectorHeartbeatTelemetry.parse(raw(wire)));}
 @Test void nativeUnlimitedMaximumIsDistinctFromMissingOrInventedZeroAndKernelCountersAreIndependent(){var unlimited=CollectorHostMemoryTelemetry.parse(raw(wire.replace("\"maximum_bytes\":201326592","\"maximum_bytes\":null")));assertNull(unlimited.sample().maximumBytes());assertThrows(RuntimeException.class,()->CollectorHostMemoryTelemetry.parse(raw(wire.replace("\"maximum_bytes\":201326592,",""))));assertThrows(RuntimeException.class,()->CollectorHostMemoryTelemetry.parse(raw(wire.replace("\"maximum_bytes\":201326592","\"maximum_bytes\":0"))));assertEquals(2,CollectorHostMemoryTelemetry.parse(raw(wire.replace("\"oom_kills\":0","\"oom_kills\":2"))).sample().oomKills());assertNotEquals(unlimited.payloadHash(),CollectorHostMemoryTelemetry.parse(raw(wire)).payloadHash());}
 @Test void MissingDuplicateUnknownWrongVersionAndInvalidExactValuesFailClosed(){for(String key:new String[]{"sequence","pid","rss_bytes","maximum_bytes","oom_events","oom_kills"}){for(String bad:new String[]{"-1","1.0","\"1\"","9007199254740992"}){String changed=wire.replaceFirst(java.util.regex.Pattern.quote("\""+key+"\":")+"[0-9]+",java.util.regex.Matcher.quoteReplacement("\""+key+"\":"+bad));assertThrows(RuntimeException.class,()->CollectorHostMemoryTelemetry.parse(raw(changed)));}}for(String bad:new String[]{wire.replace("{","{\"sequence\":1,"),wire.replace("{","{\"healthy\":true,"),wire.replace("collector-host-memory-v1","collector-host-memory-v2"),wire.replace("00:10:00.000000Z","00:10:00Z"),wire.replace("00:09:00.000000Z","00:11:00.000000Z"),wire.replace("\"rss_bytes\":1048576","\"rss_bytes\":0"),wire.replace("\"pid\":12","\"pid\":0"),wire.replace("\"sequence\":1","\"sequence\":0")})assertThrows(RuntimeException.class,()->CollectorHostMemoryTelemetry.parse(raw(bad)));assertThrows(RuntimeException.class,()->CollectorHostMemoryTelemetry.parse(new byte[8193]));assertThrows(RuntimeException.class,()->CollectorHostMemoryTelemetry.parse(null));}
 @Test void typedConstructionCannotBypassLifetimeIdentityPrecisionAndNumericBounds(){var at=Instant.parse("2026-01-01T00:10:00Z");var original=CollectorHostMemoryTelemetry.parse(raw(wire)).sample();assertThrows(RuntimeException.class,()->new CollectorHostMemoryTelemetry.Sample(original.captureEpoch(),original.processIdentity(),at.plusSeconds(1),1,12,at,1048576,original.cgroupEpoch(),null,0,0));assertThrows(RuntimeException.class,()->new CollectorHostMemoryTelemetry.Sample(original.captureEpoch(),original.processIdentity(),at,1,12,at.plusNanos(1),1048576,original.cgroupEpoch(),null,0,0));assertThrows(RuntimeException.class,()->new CollectorHostMemoryTelemetry.Sample(original.captureEpoch(),"bad",at,1,12,at,1048576,original.cgroupEpoch(),null,0,0));}
}
